const request = require('supertest');
const app = require('../../index');

describe('A.3: Yêu cầu Chỉnh sửa (POST /:id/request-revision)', () => {
    beforeEach(() => { jest.clearAllMocks(); });

    it('[Real Payload] [EP] ORD-REV-06 - Lỗi sai trạng thái đơn hàng (pending)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ id: 9, status: 'completed' }]]).mockResolvedValueOnce([[{ affectedRows: 1 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "comment": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`); } catch(e) { payload = `{
    "comment": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`; }
        const res = await request(app)
            .post('/9/request-revision')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
    it('[Real Payload] [EP] ORD-REV-07 - Lỗi sai trạng thái đơn hàng (paid)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ id: 9, status: 'completed' }]]).mockResolvedValueOnce([[{ affectedRows: 1 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "comment": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`); } catch(e) { payload = `{
    "comment": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`; }
        const res = await request(app)
            .post('/9/request-revision')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
    it('[Real Payload] [HP] ORD-REV-01 - Yêu cầu hợp lệ cho đơn completed', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ id: 9, status: 'completed' }]]).mockResolvedValueOnce([[{ affectedRows: 1 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "comment": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`); } catch(e) { payload = `{
    "comment": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`; }
        const res = await request(app)
            .post('/9/request-revision')
            .send(payload);
        
        expect(res.status).toBe(200);
    });
    it('[Real Payload] [BVA] ORD-REV-02 - Yêu cầu hợp lệ cho đơn fixed (tại min)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ id: 9, status: 'completed' }]]).mockResolvedValueOnce([[{ affectedRows: 1 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "comment": "A"
}`); } catch(e) { payload = `{
    "comment": "A"
}`; }
        const res = await request(app)
            .post('/9/request-revision')
            .send(payload);
        
        expect(res.status).toBe(200);
    });
    it('[Real Payload] [BVA] ORD-REV-03 - Yêu cầu hợp lệ tại max', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ id: 9, status: 'completed' }]]).mockResolvedValueOnce([[{ affectedRows: 1 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "comment": ""
}`); } catch(e) { payload = `{
    "comment": ""
}`; }
        const res = await request(app)
            .post('/9/request-revision')
            .send(payload);
        
        expect(res.status).toBe(200);
    });
    it('[Real Payload] [BVA] ORD-REV-04 - Lỗi comment rỗng', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ id: 9, status: 'completed' }]]).mockResolvedValueOnce([[{ affectedRows: 1 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "comment": ""
}`); } catch(e) { payload = `{
    "comment": ""
}`; }
        const res = await request(app)
            .post('/9/request-revision')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
    it('[Real Payload] [BVA] ORD-REV-05 - Lỗi comment vượt mức max', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ id: 9, status: 'completed' }]]).mockResolvedValueOnce([[{ affectedRows: 1 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "comment": ""
}`); } catch(e) { payload = `{
    "comment": ""
}`; }
        const res = await request(app)
            .post('/9/request-revision')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
});